const NOW = Date.now();
const cfg = (($('Config ophalen').all()[0]||{}).json)||{};
const TH  = (cfg.thresholds && cfg.thresholds.default) || {};
const OFFLINE_MIN = TH.offline_min ?? 10, UPD_MANY = TH.updates_many ?? 20;
const BAT_MIN = TH.bat_min ?? 15, DISK_WARN = TH.disk_warn ?? 80, DISK_ALARM = TH.disk_alarm ?? 90;
const TEMP_ALARM = TH.temp_alarm ?? 90;
const num = v => (v==null||v==='')?NaN:Number(v);
const tms = r => Date.parse(r.ts);
const hhmm = () => new Date(NOW).toLocaleTimeString('nl-NL',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Amsterdam'});
const asArr = v => Array.isArray(v)?v:(typeof v==='string'?(()=>{try{return JSON.parse(v)}catch(e){return null}})():null);
const rows = $input.all().map(i=>i.json);          // v_latest: 1 rij per machine
const online = rows.filter(r=>!isNaN(tms(r)) && (NOW-tms(r))/60000 <= OFFLINE_MIN);
const label = m => (m||'?');

const t=hhmm(); const store=$getWorkflowStaticData('global'); store.a=store.a||{};
const out=[]; const t2=(m,k)=>m+':'+k;
function fire(m,key,active,spec,caption){
  const id=t2(m,key); const was=!!store.a[id];
  if(active && !was){ store.a[id]=true; out.push({json:{caption,spec}}); }
  else if(!active && was){ store.a[id]=false;
    out.push({json:{caption:'\u2713 Opgelost \u2014 '+m+' \u00b7 '+t,
      spec:{title:'\u2713 Opgelost \u2014 '+m,subtitle:t,state:'ok',
        rows:[{label:key.toUpperCase(),value:'weer OK',status:'ok'}],footer:'SysDash \u00b7 hersteld \u00b7 '+t}}}); }
}
// per machine de vitale checks
for(const d of rows){
  const m=label(d.machine); const off=isNaN(tms(d))||(NOW-tms(d))/60000>OFFLINE_MIN;
  fire(m,'offline',off,{title:'\u25B2 OFFLINE \u2014 '+m,subtitle:'sinds '+t,state:'alert',
    rows:[{label:'MACHINE',value:'geen data > '+OFFLINE_MIN+' min',status:'high'}],footer:'SysDash \u00b7 offline \u00b7 '+t},
    '\u25B2 OFFLINE \u2014 '+m+' \u00b7 '+t);
  if(off) continue; // rest alleen als 'ie online is
  const disk=num(d.disk), temp=num(d.temp), up=d.net_up;
  fire(m,'disk',!isNaN(disk)&&disk>=DISK_ALARM,{title:'\u25B2 SCHIJF VOL \u2014 '+m,subtitle:t,state:'alert',
    rows:[{label:'SCHIJF',value:Math.round(disk)+'%',pct:disk,status:'high'}],footer:'SysDash \u00b7 schijf \u00b7 '+t},
    '\u25B2 SCHIJF VOL \u2014 '+m+' \u00b7 '+Math.round(disk)+'%');
  fire(m,'temp',!isNaN(temp)&&temp>=TEMP_ALARM,{title:'\u25B2 TE HEET \u2014 '+m,subtitle:t,state:'alert',
    rows:[{label:'TEMP',value:Math.round(temp)+'\u00b0C',status:'high'}],footer:'SysDash \u00b7 temp \u00b7 '+t},
    '\u25B2 TE HEET \u2014 '+m+' \u00b7 '+Math.round(temp)+'\u00b0C');
  fire(m,'net',up===false,{title:'\u25B2 GEEN INTERNET \u2014 '+m,subtitle:t,state:'alert',
    rows:[{label:'NETWERK',value:'geen verbinding',status:'high'}],footer:'SysDash \u00b7 netwerk \u00b7 '+t},
    '\u25B2 GEEN INTERNET \u2014 '+m+' \u00b7 '+t);
}
return out;
